window.__SITE_EN={"AI rà soát hợp đồng":"AI rà soát hợp đồng","Clause — Đọc kỹ từng dòng trước khi đặt bút ký":"Clause — Review every line before you sign","Chuyển đến nội dung chính":"Skip to content","Cách đọc duyệt":"How it reviews","Thử hợp đồng":"Sample contracts","Sổ tay quy tắc":"Playbook","Bảng giá":"Pricing","Hỏi đáp":"FAQ","Bắt đầu rà soát":"Start reviewing","Đặt bút ký":"Sign","với đôi mắt":"with your eyes","nhắm":"shut","mở to.":"wide open.","Clause đọc hợp đồng theo đúng cách một luật sư cẩn trọng làm việc: soi kỹ từng dòng, đối chiếu với những nguyên tắc mà đội ngũ của bạn thực sự nắm giữ. Hệ thống gắn cờ điều khoản rủi ro, giải thích dễ hiểu và soạn sẵn phương án sửa đổi. Thường chỉ mất chưa đầy một phút.":"Clause reviews contracts just like a meticulous attorney: inspecting every line against the principles your team actually operates by. It flags risky clauses, explains them in plain English, and drafts ready-to-accept redlines. Usually in under a minute.","Thử hợp đồng mẫu":"Try a sample contract","Xem cách đọc duyệt":"See how it works","Nhận file Word & PDF, xuất file kèm vết sửa đổi":"Accepts Word & PDF, exports with tracked changes","Tài liệu của bạn không bao giờ dùng để huấn luyện AI":"Your documents are never used to train AI","HỢP ĐỒNG DỊCH VỤ TỔNG THỂ":"MASTER SERVICES AGREEMENT","Dịch vụ bắt đầu vào Ngày Hiệu Lực và duy trì trong suốt Thời Hạn Ban Đầu.":"Services shall commence on the Effective Date and continue throughout the Initial Term.","Hợp đồng này tự động gia hạn các kỳ tiếp theo kéo dài":"This Agreement shall automatically renew for successive periods of","hai mươi bốn (24) tháng":"twenty-four (24) months","trừ khi có thông báo trước 180 ngày.":"unless notice is given 180 days prior.","Khách hàng sẽ bồi thường cho Nhà cung cấp trước":"Client shall indemnify and hold harmless Provider against","mọi tổn thất":"any and all losses",", bất kể phát sinh dưới hình thức nào.":", howsoever arising.","Điều · 4.2":"Clause · 4.2","Trung bình":"Medium","Tự động gia hạn 2 năm với thời hạn báo trước 6 tháng. Đề xuất sửa thành 12 tháng và báo trước 30 ngày.":"2-year auto-renewal with 6-month notice period. Proposed amendment: 12 months with 30-day notice.","Điều · 9.3":"Clause · 9.3","Bồi thường một chiều không giới hạn mức trần. Hãy chuyển thành hai chiều và giới hạn ở mức phí đã thanh toán.":"Uncapped unilateral indemnification. Convert to mutual indemnification capped at total fees paid.","Đã duyệt · 38 giây · 4 vấn đề":"Reviewed · 38s · 4 issues","thời gian duyệt trung vị, hợp đồng 20 trang":"median review time, 20-page contract","loại điều khoản hệ thống nhận diện":"clause types recognized","đề xuất viết lại được chấp thuận":"redline acceptance rate","hợp đồng bị dùng để huấn luyện mô hình":"contracts used to train models","Từng dòng một,":"Line by line,","như con người đọc":"read like a human","01 — PHÂN TÁCH":"01 — PARSE","Nhận diện cấu trúc":"Structure recognition","Clause tách văn bản thành từng điều khoản, định nghĩa và tham chiếu chéo, để cụm từ “Dịch vụ” ở mục 9 vẫn mang đúng ý nghĩa đã quy định tại mục 1.":"Clause parses the document into individual clauses, definitions, and cross-references, ensuring the term “Services” in Section 9 retains its exact meaning defined in Section 1.","02 — ĐỐI CHIẾU":"02 — COMPARE","Soi chiếu với sổ tay quy tắc":"Benchmarked against your playbook","Mọi điều khoản đều được kiểm tra với các giới hạn mà đội ngũ của bạn chấp nhận hoặc từ chối: hạn thanh toán, mức trần trách nhiệm, điều kiện gia hạn, quyền sở hữu trí tuệ.":"Every clause is measured against thresholds your team accepts or rejects: payment terms, liability caps, renewal conditions, and IP rights.","03 — GIẢI THÍCH":"03 — EXPLAIN","Diễn giải bằng lời lẽ dễ hiểu":"Plain-language explanations","Mỗi cảnh báo đi kèm một ghi chú bên lề: điều khoản đó thực sự nói gì, vì sao nó ảnh hưởng tới bạn, và mức độ nghiêm trọng ra sao. Không thuật ngữ rắc rối, không vòng vo.":"Every flag comes with a margin note: what the clause actually says, why it affects you, and how severe it is. No jargon, no hedging.","04 — GẠCH SỬA":"04 — REDLINE","Soạn thảo phương án sửa":"Ready-to-use redlines","Các đề xuất viết lại xuất hiện dưới dạng vết sửa đổi (tracked changes) đúng văn phong của bạn, giúp đối tác thấy rõ từng chữ được chỉnh và lý do. Bạn chỉ việc chấp nhận, sửa thêm hoặc bỏ qua.":"Proposed revisions appear as tracked changes tailored to your style, showing your counterparty exactly what changed and why. Simply accept, tweak, or reject.","Điều khoản 01 / 14":"Clause 01 / 14","Chọn một hợp đồng.":"Select a contract.","Xem hệ thống rà soát.":"Watch it review.","Ba bản hợp đồng mẫu được biên soạn riêng cho trang này và hoàn toàn giả định. Hãy chọn một bản và nhấn Rà soát: các điều khoản rủi ro sẽ lần lượt sáng lên kèm ghi chú và câu chữ đề xuất sửa đổi để bạn chấp nhận ngay.":"Three sample agreements crafted for this demo, entirely fictional. Pick one and click Review: risky clauses will highlight one by one with notes and proposed redlines you can accept instantly.","8 điều khoản":"8 clauses","Rủi ro hợp đồng":"Contract risk","Chưa rà soát":"Unreviewed","Nhấn Rà soát để bắt đầu đọc.":"Click Review to begin reading.","Rà soát hợp đồng này":"Review this contract","← Trước":"← Prev","Tiếp →":"Next →","Chấp nhận tất cả":"Accept all","Các bản hợp đồng mẫu và các bên liên quan đều là giả định, quy trình rà soát được lập trình sẵn cho bản thiết kế concept này. Clause không phải là công ty luật và không nội dung nào tại đây mang tính tư vấn pháp lý.":"Sample agreements and parties are fictional; the review flow is pre-programmed for this design concept. Clause is not a law firm and nothing here constitutes legal advice.","Nguyên tắc của bạn,":"Your rules,","ghi rõ thành văn":"codified in writing","Ngay khi khởi tạo, Clause đã nắm sẵn 40 nguyên tắc thương lượng mà hầu hết các đội ngũ tinh gọn quan tâm. Bạn chỉ cần chỉnh sửa bất kỳ mục nào bằng một câu tự nhiên (“chúng tôi không bao giờ chấp nhận hạn thanh toán quá 45 ngày”) và mọi lần rà soát sau đó sẽ tự động tuân theo.":"Out of the box, Clause comes with 40 negotiation baselines lean teams care about. Simply edit any rule in plain English (“we never accept payment terms over 45 days”) and every subsequent review automatically complies.","Nguyên tắc mặc định, tùy chỉnh toàn bộ":"Default rules, fully customizable","Rẻ hơn nhiều":"Far cheaper than","một điều khoản bất lợi":"a single bad clause","Mọi gói dịch vụ đều bao gồm ghi chú giải thích dễ hiểu, đề xuất viết lại kèm vết sửa đổi và sổ tay quy tắc tùy chỉnh. Thanh toán theo năm tiết kiệm hai tháng chi phí.":"All plans include plain-language explanations, redline proposals with tracked changes, and a custom playbook. Billed annually to save two months.","Theo tháng":"Monthly","Theo năm":"Annual","Phụ lục A":"Schedule A","Cho cá nhân":"For individuals","/ tháng":"/ month","20 lượt rà soát mỗi tháng":"20 reviews per month","Sổ tay quy tắc mặc định, cho phép sửa":"Default playbook, editable","Xuất file Word và PDF":"Word & PDF export","Bắt đầu gói Solo":"Start Solo plan","Phổ biến nhất":"Most popular","Phụ lục B":"Schedule B","Theo thành viên":"Per seat","/ người / tháng":"/ seat / month","Rà soát không giới hạn":"Unlimited reviews","Sổ tay quy tắc dùng chung toàn nhóm":"Shared team playbook","Luồng phê duyệt và nhật ký kiểm toán":"Approval workflows & audit logs","Tích hợp công cụ chữ ký điện tử":"E-signature integration","Dùng thử gói Team":"Try Team plan","Phụ lục C":"Schedule C","Cho văn phòng luật":"For law firms","Liên hệ":"Contact us","Triển khai hạ tầng riêng biệt":"Dedicated infrastructure deployment","Biến hợp đồng mẫu của bạn thành quy tắc":"Turn your past contracts into playbook rules","Phân quyền theo từng hồ sơ vụ việc":"Granular permissions per matter","Luật sư chuyên trách hỗ trợ triển khai":"Dedicated legal engineer onboarding","Trò chuyện cùng chúng tôi":"Talk to us","Câu hỏi thường gặp":"Frequently asked questions","Những dòng chữ nhỏ":"The fine print","về chúng tôi":"about us","Hợp đồng tiếp theo,":"Your next contract,","được đọc thấu đáo":"thoroughly read","Miễn phí 14 ngày cho mọi gói dịch vụ. Hãy thử tải lên một bản hợp đồng bạn từng ký và xem Clause sẽ nhận xét những gì.":"14-day free trial on all plans. Upload an old contract and see what Clause finds.","Email công việc":"Work email","Bắt đầu dùng thử miễn phí":"Start free trial","Công cụ rà soát hợp đồng dành cho những người luôn đọc kỹ điều khoản, và cả những ai muốn bắt đầu thói quen đó.":"Contract review software for people who always read the fine print — and those who wish they did.","Sản phẩm":"Product","Công ty":"Company","Bảo mật":"Security","Pháp lý":"Legal","Điều khoản":"Terms","Quyền riêng tư":"Privacy","Miễn trừ tư vấn pháp lý":"Legal disclaimer","Thiết kế concept — thương hiệu giả định.":"Concept design — fictional brand.","Clause rà soát hợp đồng từng dòng đối chiếu với bộ quy tắc của riêng bạn, giải thích mọi điều khoản rủi ro bằng ngôn ngữ đời thường và soạn thảo bản sửa đổi để bạn chấp nhận ngay.":"Clause reviews contracts line by line against your own playbook, explains every risky clause in plain English, and drafts revisions ready for immediate acceptance.","Clause, trang chủ":"Clause, homepage","Điều hướng chính":"Main navigation","Mở menu":"Open menu","Đặt bút ký với đôi mắt mở to.":"Sign with your eyes wide open.","Clause qua những con số":"Clause in numbers","Hợp đồng mẫu":"Sample contracts","Nội dung hợp đồng":"Contract text","Vấn đề trước":"Previous issue","Vấn đề tiếp theo":"Next issue","Ghi chú rà soát":"Review notes","Chu kỳ thanh toán":"Billing cycle","Thiết kế tự do":"Freelance Design","Hợp đồng Dịch vụ Thiết kế":"Design Services Agreement","Giữa Công ty TNHH Northfold Studio (“Khách hàng”) và nhà thiết kế có tên tại Phụ lục C (“Nhà thiết kế”).":"Between Northfold Studio Ltd. (“Client”) and the designer named in Schedule C (“Designer”).","Phạm vi dịch vụ":"Scope of Services","Nhà thiết kế sẽ cung cấp dịch vụ thiết kế nhận diện thương hiệu được mô tả tại Phụ lục A (“Dịch vụ”) và bất kỳ dịch vụ bổ sung nào mà Khách hàng yêu cầu hợp lý trong Thời hạn hợp đồng.":"Designer will provide brand identity design services described in Schedule A (“Services”) and any additional services reasonably requested by Client during the Term.","Phạm vi công việc mở không giới hạn":"Uncapped open scope of work","Cụm từ “bất kỳ dịch vụ bổ sung nào mà Khách hàng yêu cầu hợp lý” đồng nghĩa việc phát sinh có thể bị thêm vào mà không có phí hay thời hạn mới.":"The phrase “any additional services reasonably requested” means scope creep can be added without additional fees or updated deadlines.","Nhà thiết kế sẽ cung cấp dịch vụ thiết kế nhận diện thương hiệu được mô tả tại Phụ lục A (“Dịch vụ”). Mọi công việc phát sinh ngoài phạm vi sẽ được thỏa thuận bằng văn bản và tính phí theo đơn giá ngày của Nhà thiết kế.":"Designer will provide brand identity design services described in Schedule A (“Services”). Any out-of-scope work will be agreed in writing and billed at Designer’s day rate.","Phí và thanh toán":"Fees and Payment","Khách hàng sẽ thanh toán các khoản phí tại Phụ lục B trong vòng chín mươi (90) ngày kể từ ngày nhận được hóa đơn hợp lệ.":"Client shall pay fees set forth in Schedule B within ninety (90) days of receipt of a valid invoice.","Hạn thanh toán kéo dài 90 ngày":"Extended 90-day payment term","Ba tháng là quãng thời gian quá dài để chờ nhận thù lao cho công sức bạn đã bỏ ra, và cũng không có chế tài nào ngăn việc chậm trả.":"Three months is far too long to wait for payment on completed work, and there is no penalty clause for late payment.","Khách hàng sẽ thanh toán các khoản phí tại Phụ lục B trong vòng ba mươi (30) ngày kể từ ngày nhận được hóa đơn hợp lệ. Khoản thanh toán chậm sẽ chịu lãi suất 4%/năm cộng biên độ cơ sở.":"Client shall pay fees set forth in Schedule B within thirty (30) days of receipt of a valid invoice. Late payments shall incur interest at 4% per annum above the base rate.","Sở hữu trí tuệ":"Intellectual Property","Toàn bộ quyền sở hữu trí tuệ do Nhà thiết kế tạo ra, dù có liên quan đến Dịch vụ hay không, đều được chuyển giao cho Khách hàng ngay khi khởi tạo.":"All intellectual property created by Designer, whether related to the Services or not, shall transfer to Client upon creation.","Nguy cơ mất quyền sở hữu mọi tác phẩm":"Risk of losing rights to all creations","Cụm từ “dù có liên quan đến Dịch vụ hay không” bao trùm cả sản phẩm bạn làm cho khách hàng khác. Hơn nữa quyền sở hữu chuyển giao trước cả khi bạn được trả tiền.":"The phrase “whether related to the Services or not” captures work created for other clients. Furthermore, IP transfers before you are paid.","Quyền sở hữu trí tuệ đối với sản phẩm bàn giao cuối cùng sẽ chuyển sang Khách hàng sau khi thanh toán đầy đủ. Nhà thiết kế giữ toàn quyền đối với tư liệu có sẵn, bản phác thảo không sử dụng và bí quyết nghề nghiệp.":"Intellectual property rights in final deliverables will transfer to Client upon payment in full. Designer retains all rights to background materials, unused drafts, and know-how.","Hồ sơ năng lực (Portfolio)":"Portfolio Rights","Nhà thiết kế không được phép nhắc tới Khách hàng hoặc Dịch vụ trên bất kỳ phương tiện nào.":"Designer may not refer to Client or the Services in any medium.","Cấm đưa vào hồ sơ năng lực":"Total portfolio ban","Bạn sẽ không thể giới thiệu dự án này cho các khách hàng tương lai, ngay cả khi sản phẩm đã ra mắt công chúng.":"You will be unable to showcase this work to prospective clients, even after it has launched publicly.","Nhà thiết kế được phép trưng bày sản phẩm hoàn thiện trong hồ sơ năng lực sau khi Khách hàng đã công bố rộng rãi, trừ khi Khách hàng có văn bản phản đối.":"Designer may display completed work in their portfolio once Client has released it publicly, unless Client objects in writing.","Chấm dứt hợp đồng":"Termination","Khách hàng có thể chấm dứt Hợp đồng này bất kỳ lúc nào mà không cần báo trước. Không phát sinh nghĩa vụ thanh toán cho các hạng mục đang thực hiện dở dang.":"Client may terminate this Agreement at any time without notice. No payment obligation shall arise for work-in-progress.","Đơn phương chấm dứt, không trả phí phần đã làm":"Unilateral cancellation without pay for work done","Khách hàng có thể dừng dự án ngay ngày mai và không phải trả đồng nào cho hàng tuần làm việc bạn đã bỏ ra.":"Client could pull the plug tomorrow without paying a single dollar for weeks of effort already expended.","Mỗi bên có thể chấm dứt Hợp đồng này bằng văn bản báo trước mười bốn (14) ngày. Khách hàng sẽ thanh toán đầy đủ cho toàn bộ khối lượng công việc đã hoàn thành tính đến ngày chấm dứt.":"Either party may terminate this Agreement upon fourteen (14) days’ written notice. Client will pay in full for all work completed up to the termination date.","Bảo mật thông tin":"Confidentiality","Mỗi bên cam kết giữ bí mật thông tin bảo mật của bên kia trong suốt Thời hạn hợp đồng và hai năm tiếp theo.":"Each party agrees to hold the other party’s confidential information in confidence during the Term and for two years thereafter.","Trách nhiệm pháp lý":"Liability","Trách nhiệm bồi thường của Nhà thiết kế theo Hợp đồng này là không giới hạn.":"Designer’s liability under this Agreement shall be unlimited.","Trách nhiệm bồi thường vô hạn":"Unlimited liability","Một sai sót nhỏ trên file logo về lý thuyết có thể khiến bạn phải đền bù số tiền lớn hơn cả tổng giá trị dự án. Hầu hết hợp đồng đều đặt mức trần.":"A minor file error could theoretically expose you to damages exceeding the total value of the project. Standard practice requires a cap.","Tổng trách nhiệm bồi thường của mỗi bên theo Hợp đồng này được giới hạn ở tổng mức phí đã thanh toán trong mười hai (12) tháng trước thời điểm phát sinh yêu cầu bồi thường.":"Each party’s aggregate liability under this Agreement is capped at total fees paid in the twelve (12) months preceding the claim.","Toàn bộ thỏa thuận":"Entire Agreement","Hợp đồng này cùng các Phụ lục đính kèm cấu thành toàn bộ thỏa thuận giữa hai bên về Dịch vụ.":"This Agreement together with its Schedules constitutes the entire agreement between the parties regarding the Services.","Thuê bao phần mềm":"Software Subscription","Hợp đồng Thuê bao Phần mềm":"Software Subscription Agreement","Giữa Lumenbase Inc. (“Nhà cung cấp”) và khách hàng có tên tại Đơn đặt hàng (“Khách hàng”).":"Between Lumenbase Inc. (“Provider”) and the customer named in the Order Form (“Customer”).","Thời hạn và gia hạn":"Term and Renewal","Gói thuê bao tự động gia hạn các kỳ tiếp theo kéo dài hai mươi bốn (24) tháng trừ khi Khách hàng gửi thông báo bằng văn bản ít nhất một trăm tám mươi (180) ngày trước ngày gia hạn.":"The subscription will automatically renew for successive twenty-four (24) month terms unless Customer gives written notice at least one hundred eighty (180) days prior to renewal.","Phải báo hủy trước tận sáu tháng":"Six-month notice window to cancel","Chỉ cần quên mốc thời gian nửa năm trước ngày gia hạn là bạn sẽ bị ràng buộc thêm hai năm nữa.":"Miss a date six months before renewal and you are locked in for two more years.","Gói thuê bao tự động gia hạn các kỳ tiếp theo kéo dài mười hai (12) tháng trừ khi một trong hai bên gửi văn bản thông báo ít nhất ba mươi (30) ngày trước ngày gia hạn.":"The subscription will automatically renew for successive twelve (12) month terms unless either party gives written notice at least thirty (30) days prior to renewal.","Biểu phí":"Fees","Nhà cung cấp có thể thay đổi mức phí bất kỳ lúc nào bằng cách công bố bảng giá mới trên trang web của mình.":"Provider may alter fees at any time by posting updated rates on its website.","Giá có thể tăng bất cứ lúc nào":"Price can increase at any time","Không cần báo trước, không giới hạn mức tăng và không có quyền hủy hợp đồng nếu giá tăng gấp đôi giữa kỳ.":"No notice required, no cap on increases, and no termination right if fees double mid-term.","Nhà cung cấp chỉ có thể điều chỉnh phí mỗi năm một lần với văn bản báo trước sáu mươi (60) ngày. Mức tăng tối đa không quá 5% và áp dụng vào kỳ gia hạn tiếp theo.":"Provider may adjust fees once per year with sixty (60) days’ written notice. Increases capped at 5% and effective upon next renewal.","Thanh toán":"Payment","Phí thuê bao được xuất hóa đơn trả trước theo năm và thanh toán trong vòng ba mươi (30) ngày kể từ ngày xuất hóa đơn.":"Subscription fees are invoiced annually in advance and payable within thirty (30) days of invoice date.","Sử dụng Dữ liệu Khách hàng":"Use of Customer Data","Nhà cung cấp có thể sử dụng Dữ liệu Khách hàng để cải tiến sản phẩm và dịch vụ, bao gồm cả việc huấn luyện các mô hình học máy.":"Provider may use Customer Data to improve products and services, including training machine learning models.","Dữ liệu của bạn có thể bị dùng để huấn luyện AI":"Your data may be used to train AI","Mọi thông tin bạn đưa lên hệ thống, kể cả hồ sơ mật của khách hàng, đều có thể bị dùng để xây dựng tính năng cho người khác.":"Everything uploaded to the system, including confidential client files, could be used to train models for competitors.","Nhà cung cấp chỉ sử dụng Dữ liệu Khách hàng nhằm mục đích cung cấp Dịch vụ cho Khách hàng. Nhà cung cấp cam kết không dùng Dữ liệu Khách hàng để huấn luyện mô hình khi chưa có sự đồng ý bằng văn bản.":"Provider will use Customer Data solely to provide Services to Customer. Provider will not use Customer Data for model training without prior written consent.","Độ sẵn sàng của hệ thống":"System Availability","Nhà cung cấp sẽ nỗ lực hợp lý về mặt thương mại để duy trì Dịch vụ hoạt động.":"Provider will use commercially reasonable efforts to keep the Services available.","Không cam kết tỷ lệ hoạt động (Uptime)":"No guaranteed uptime SLA","“Nỗ lực hợp lý về mặt thương mại” không phải là con số cụ thể. Nếu hệ thống sập cả tuần, bạn không có cơ sở nào để yêu cầu hoàn tiền.":"“Commercially reasonable efforts” is not an enforceable uptime SLA. If downtime spans a week, there is no contractual remedy.","Nhà cung cấp cam kết duy trì Dịch vụ hoạt động 99,9% thời gian mỗi tháng. Với mỗi 0,1% thấp hơn mức này, Khách hàng được khấu trừ 10% phí thuê bao của tháng đó.":"Provider guarantees 99.9% monthly uptime. For every 0.1% below this threshold, Customer receives a 10% credit against that month’s fee.","Kết thúc thuê bao":"Subscription Termination","Khi Gói thuê bao kết thúc, Dữ liệu Khách hàng sẽ bị xóa ngay lập tức.":"Upon termination of the subscription, Customer Data will be deleted immediately.","Không có thời gian sao lưu dữ liệu":"No data export grace period","Toàn bộ hồ sơ của bạn biến mất ngay khoảnh khắc hợp đồng hết hạn mà không có cơ hội xuất dữ liệu ra.":"All records vanish the moment the contract expires without an opportunity to export your data.","Trong vòng ba mươi (30) ngày sau khi Gói thuê bao kết thúc, Khách hàng có quyền xuất toàn bộ dữ liệu của mình. Sau thời hạn đó Nhà cung cấp sẽ xóa dữ liệu và xác nhận bằng văn bản.":"Customer may export all data within thirty (30) days following termination. Thereafter, Provider will delete the data and confirm in writing.","Giới hạn trách nhiệm":"Limitation of Liability","Tổng trách nhiệm bồi thường của Nhà cung cấp được giới hạn ở mức phí đã thanh toán trong một (1) tháng trước khi phát sinh khiếu nại.":"Provider’s total liability is limited to fees paid in the one (1) month preceding the claim.","Mức trần bồi thường chỉ bằng một tháng phí":"Liability cap equal to just one month of fees","Nếu họ làm mất dữ liệu của bạn, khoản đền bù tối đa bạn nhận được chỉ tương đương một tháng thuê bao.":"If a data breach occurs, your maximum recovery is capped at a single monthly fee.","Tổng trách nhiệm bồi thường của mỗi bên được giới hạn ở mức phí đã thanh toán trong mười hai (12) tháng trước khiếu nại, riêng vi phạm bảo vệ dữ liệu được giới hạn ở mức gấp ba lần khoản đó.":"Each party’s aggregate liability is capped at fees paid in the twelve (12) months preceding the claim, or 3x that amount for data protection breaches.","Thông báo":"Notices","Mọi thông báo phải được lập thành văn bản và gửi tới địa chỉ email ghi trong Đơn đặt hàng.":"All notices must be in writing and sent to email addresses specified in the Order Form.","Thuê mặt bằng studio":"Studio Lease","Hợp đồng Thuê Căn số 4, Khu Copperline Yard":"Lease of Unit 4, Copperline Yard","Giữa Công ty Bất động sản Copperline (“Bên cho thuê”) và bên thuê có tên tại Bản thông tin chi tiết (“Bên thuê”).":"Between Copperline Properties Ltd. (“Landlord”) and the tenant named in the Particulars (“Tenant”).","Tiền thuê":"Rent","Tiền thuê được thanh toán trước theo từng quý vào các ngày đầu quý thông lệ.":"Rent is payable quarterly in advance on standard quarter days.","Điều chỉnh tiền thuê":"Rent Review","Tiền thuê sẽ được xem xét điều chỉnh vào mỗi dịp kỷ niệm ngày bắt đầu Thời hạn thuê và chỉ có thể điều chỉnh tăng.":"Rent will be reviewed on each anniversary of the Term and may only adjust upwards.","Chỉ tăng không giảm, điều chỉnh hàng năm":"Upwards-only annual rent review","Tiền thuê có thể tăng lên mỗi năm và không bao giờ giảm xuống, ngay cả khi giá mặt bằng khu vực đi xuống.":"Rent can increase every single year and never decrease, even if surrounding market rents plunge.","Tiền thuê sẽ được xem xét mỗi ba năm một lần theo Chỉ số Giá tiêu dùng (CPI), mức tăng trần 4%/năm, và có thể tăng hoặc giảm tùy theo thị trường.":"Rent will be reviewed every three years indexed to CPI, capped at 4% per annum, and may adjust upwards or downwards based on market conditions.","Sửa chữa và bảo trì":"Repair and Maintenance","Bên thuê phải duy trì toàn bộ Tòa nhà, bao gồm cả phần mái và kết cấu chính, trong tình trạng tốt.":"Tenant must keep the entire Building, including roof and primary structure, in good repair.","Bạn phải gánh chi phí sửa cả tòa nhà":"You bear the repair burden for the whole building","Bạn chỉ thuê một căn studio nhỏ nhưng điều khoản này bắt bạn chịu trách nhiệm cho cả mái nhà và kết cấu của toàn bộ tòa nhà.":"You are leasing an individual studio unit, but this clause makes you liable for the entire building’s roof and structural envelope.","Bên thuê có trách nhiệm giữ gìn phần nội thất bên trong Căn thuê không xuống cấp hơn so với hiện trạng ban đầu được ghi nhận tại biên bản bàn giao.":"Tenant is responsible for keeping the interior of the Unit in no worse state than documented in the initial schedule of condition.","Phí dịch vụ":"Service Charge","Bên thuê sẽ thanh toán một phần hợp lý trong toàn bộ chi phí mà Bên cho thuê chi trả liên quan đến Tòa nhà.":"Tenant will pay a fair proportion of all costs incurred by Landlord in connection with the Building.","Phí dịch vụ không có mức trần":"Uncapped service charge","“Toàn bộ chi phí” không kèm mức trần hay bảng kê có thể bao gồm cả những hạng mục nâng cấp chỉ mang lại lợi ích cho chủ nhà.":"“All costs” with no cap or itemization could include capital improvements that solely benefit the landlord.","Bên thuê sẽ thanh toán tỷ lệ hợp lý trong các chi phí vận hành khu vực chung, giới hạn tối đa £4.50 trên mỗi foot vuông mỗi năm, kèm bảng quyết toán chi phí thực tế hàng năm.":"Tenant will pay a fair proportion of common-area operating expenses, capped at £4.50 per square foot per annum, with annual reconciled accounts.","Mục đích sử dụng":"Permitted Use","Căn thuê chỉ được sử dụng làm studio thiết kế và văn phòng làm việc, không dùng cho mục đích nào khác.":"The Unit may be used solely as a design studio and office, and for no other purpose.","Chấm dứt thuê trước hạn":"Early Termination","Bên thuê không có quyền chấm dứt Hợp đồng thuê này trước khi hết Thời hạn thuê.":"Tenant has no right to break or terminate this Lease prior to expiration of the Term.","Không có lối thoát suốt mười năm":"No break clause for ten years","Dù quy mô studio của bạn mở rộng, thu hẹp hay chuyển đi nơi khác, bạn vẫn phải trả tiền thuê đến tận ngày cuối cùng.":"Whether your studio outgrows the space, downsizes, or relocates, you remain on the hook for rent through the final day.","Bên thuê có quyền chấm dứt Hợp đồng thuê vào năm thứ ba hoặc năm thứ sáu của Thời hạn thuê bằng cách gửi văn bản thông báo trước ít nhất sáu (6) tháng.":"Tenant may terminate this Lease at the end of Year 3 or Year 6 by giving at least six (6) months’ prior written notice.","Tiền đặt cọc":"Security Deposit","Bên thuê sẽ nộp khoản tiền đặt cọc tương đương mười hai tháng tiền thuê, được hoàn trả theo quyết định riêng của Bên cho thuê.":"Tenant will pay a deposit equal to twelve months’ rent, refundable at Landlord’s sole discretion.","Cọc cả năm tiền thuê, hoàn trả “tùy ý chủ nhà”":"Full-year deposit refundable at Landlord’s discretion","Khoản cọc quá lớn và không có cam kết rõ ràng khi nào hay trong điều kiện nào bạn được nhận lại.":"An exorbitant deposit with no objective criteria governing when or under what conditions it will be refunded.","Bên thuê sẽ nộp khoản đặt cọc tương đương ba tháng tiền thuê, được giữ trong tài khoản riêng và hoàn trả trong vòng 28 ngày sau khi kết thúc Hợp đồng thuê, trừ đi các chi phí thiệt hại có chứng từ.":"Tenant will pay a deposit equal to three months’ rent, held in escrow and returned within 28 days of Lease expiry minus documented repairs.","Cải tạo nội thất":"Alterations","Bên thuê có thể thực hiện các thay đổi nội thất không ảnh hưởng kết cấu khi có sự đồng ý của Bên cho thuê, và Bên cho thuê không được từ chối một cách vô lý.":"Tenant may carry out non-structural internal alterations with Landlord’s consent, which shall not be unreasonably withheld.","Thấp":"Low","điều khoản":"clauses","{0} điều khoản, chưa đọc.":"{0} clauses, unreviewed.","Nhấn":"Click","và Clause sẽ đọc từ đầu đến cuối, dừng lại ở bất kỳ điểm nào trái với sổ tay quy tắc của bạn.":"and Clause will read through from start to finish, pausing at any term that conflicts with your playbook.","Rủi ro cao":"High risk","Rủi ro trung bình":"Medium risk","Rủi ro thấp":"Low risk","Đang đọc… phát hiện {0} vấn đề":"Reading… {0} issues found","{0} vấn đề · {1} đã sửa · {2} giữ nguyên":"{0} issues · {1} redlined · {2} kept as-is","Rủi ro {0}":"Risk: {0}","Đề xuất viết lại":"Proposed redline","Chấp nhận sửa":"Accept change","Giữ bản gốc":"Keep original","Đang rà soát…":"Reviewing…","Đang rà soát {0}.":"Reviewing {0}.","Rà soát lại":"Review again","Đã rà soát xong: {0} vấn đề, {1} cao, {2} trung bình, {3} thấp.":"Review complete: {0} issues, {1} high, {2} medium, {3} low.","Đã chấp nhận sửa · đã thêm vết sửa đổi":"Change accepted · tracked changes added","Đã giữ bản gốc · đã lưu vào nhật ký":"Original retained · logged in audit trail","Đã chấp nhận":"Accepted","Đã giữ":"Kept","Hoàn tác, giữ bản gốc":"Undo, keep original","Đã chấp nhận bản sửa cho điều khoản {0}. Điểm rủi ro còn {1}.":"Accepted redline for clause {0}. Remaining risk points: {1}.","Đã giữ bản gốc cho điều khoản {0}.":"Retained original for clause {0}.","Đã chấp nhận toàn bộ đề xuất sửa đổi. Bản hợp đồng có vết sửa đã sẵn sàng gửi lại đối tác.":"Accepted all proposed redlines. The marked-up contract is ready to send back to counterparty.","Thời hạn thanh toán":"Payment terms","Tối đa 30 ngày":"Up to 30 days","Gắn cờ mọi thời hạn dài hơn mức trần của bạn và các điều khoản thiếu lãi phạt chậm thanh toán.":"Flags payment terms longer than your ceiling and clauses missing late interest remedies.","Trần trách nhiệm bồi thường":"Liability cap","12 tháng phí":"12 months' fees","Gắn cờ trách nhiệm vô hạn, giới hạn một chiều và các ngoại lệ làm vô hiệu hóa mức trần.":"Flags unlimited liability, one-way caps, and carve-outs that invalidate the ceiling.","Tự động gia hạn":"Auto-renewal","12 tháng · báo trước 30 ngày":"12 months · 30 days notice","Gắn cờ các kỳ gia hạn quá dài và thời hạn báo hủy quá sớm dễ bị bỏ lỡ.":"Flags excessively long renewal terms and early notice deadlines that are easy to miss.","Quyền sở hữu tác phẩm":"Work product ownership","Khi thanh toán đủ":"Upon full payment","Gắn cờ việc chuyển giao quyền vượt ngoài phạm vi dự án hoặc chuyển giao trước khi bạn nhận đủ thù lao.":"Flags IP transfers exceeding project scope or vesting before you receive full payment.","Hai chiều, trả đủ phần đã làm":"Mutual, payment for work completed","Gắn cờ quyền đơn phương hủy ngang và các điều khoản bỏ mặc khối lượng công việc đã thực hiện không được thanh toán.":"Flags unilateral cancellation rights and provisions that leave work-in-progress unpaid.","Dữ liệu và bảo mật":"Data & confidentiality","Không huấn luyện AI":"No AI training","Gắn cờ quyền tái sử dụng dữ liệu của bạn, thời hạn bảo mật quá ngắn và thiếu cam kết xóa dữ liệu.":"Flags rights to reuse your data, abbreviated confidentiality periods, and missing data-deletion commitments.","Bồi thường thiệt hại":"Indemnification","Hai chiều, có mức trần":"Mutual, capped","Gắn cờ nghĩa vụ bồi thường một chiều và cụm từ “mọi tổn thất bất kể phát sinh dưới hình thức nào”.":"Flags unilateral indemnity obligations and open-ended phrases like “all losses howsoever arising”.","Điều chỉnh giá":"Price adjustment","Mỗi năm 1 lần, ≤ 5%":"Once per year, ≤ 5%","Gắn cờ quyền tự ý tăng giá, thiếu thông báo trước và tăng giá không giới hạn mức trần.":"Flags discretionary price hikes, lack of prior notice, and uncapped increases.","Clause có phải là luật sư không?":"Is Clause a law firm?","Không. Clause là phần mềm đọc hợp đồng đối chiếu với sổ tay quy tắc và giải thích những điểm rủi ro phát hiện được. Với những thương vụ giá trị lớn hoặc phức tạp, hãy mang ghi chú của Clause tới gặp luật sư chuyên môn: bạn sẽ tiết kiệm được rất nhiều giờ phí tư vấn của họ.":"No. Clause is software that reviews contracts against a rulebook and explains flagged risks. For high-stakes or complex deals, take Clause’s notes to your legal counsel: you'll save hours of billable consultation time.","Các bản hợp đồng tôi tải lên được xử lý thế nào?":"How are uploaded contracts handled?","Tài liệu được mã hóa khi lưu trữ, đặt tại khu vực máy chủ bạn chọn và xóa theo đúng lịch trình của bạn. Chúng tôi tuyệt đối không dùng tài liệu của bạn để huấn luyện mô hình AI, dù là của chúng tôi hay bên thứ ba.":"Documents are encrypted at rest, hosted in the server region you select, and deleted on your schedule. We never use your documents to train AI models — ours or anyone else’s.","Hệ thống hỗ trợ những loại hợp đồng nào?":"What types of contracts are supported?","Các thỏa thuận thương mại thông dụng: hợp đồng dịch vụ, thuê bao phần mềm, thỏa thuận bảo mật (NDA), hợp đồng thuê mặt bằng, cung ứng và đại lý. Nhận file Word và PDF; xuất ra file Word có sẵn vết sửa đổi (tracked changes) hoặc bản PDF sạch.":"Common commercial agreements: service contracts, SaaS subscriptions, non-disclosure agreements (NDAs), commercial leases, supply, and distribution agreements. Accepts Word and PDF; exports Word files with tracked changes or clean PDFs.","Hệ thống có học được nguyên tắc riêng của nhóm tôi không?":"Can it learn our team's custom rules?","Có. Bạn chỉ cần viết lại quy tắc bằng những câu văn tự nhiên, hoặc tải lên vài hợp đồng bạn từng ký kết để Clause trích xuất các nguyên tắc thương lượng và gợi ý cho bạn phê duyệt.":"Yes. Simply write your guidelines in plain English, or upload executed contracts for Clause to extract your preferred negotiation positions for review and approval.","Nếu hệ thống nhận định sai thì sao?":"What happens if a flag is inaccurate?","Mỗi cảnh báo đều trích dẫn chính xác từng từ ngữ trong hợp đồng mà nó phản hồi để bạn dễ dàng kiểm chứng lập luận. Khi bạn bỏ qua một cảnh báo kèm lý do, sổ tay quy tắc của nhóm sẽ ghi nhớ cho các lần sau.":"Every flag cites the exact wording in the contract that triggered it, so you can evaluate the reasoning immediately. When you dismiss a flag with a reason, your team playbook remembers it for future reviews.","Định nghĩa. Các thuật ngữ viết hoa mang ý nghĩa được quy định tại Phụ lục 1.":"Definitions. Capitalized terms shall have meanings assigned in Schedule 1.","Nhà cung cấp sẽ cung ứng các Dịch vụ được mô tả trong Đơn đặt hàng.":"Provider shall supply Services described in the Order Form.","Khách hàng sẽ cung cấp mọi sự hỗ trợ mà Nhà cung cấp có thể yêu cầu tùy từng thời điểm.":"Client shall provide all assistance Provider may reasonably request from time to time.","Nghĩa vụ mơ hồ":"Ambiguous obligation","Phí dịch vụ được thanh toán trong vòng sáu mươi (60) ngày kể từ ngày xuất hóa đơn.":"Service fees shall be paid within sixty (60) days of the invoice date.","Hạn 60 > 30 ngày":"60-day term > 30-day target","Nhà cung cấp có thể tạm ngừng Dịch vụ ngay lập tức đối với bất kỳ khoản chậm thanh toán nào.":"Provider may suspend Services immediately for any overdue payment.","Không báo trước":"No grace period","Hợp đồng này tự động gia hạn các kỳ tiếp theo kéo dài hai mươi bốn (24) tháng.":"This Agreement automatically renews for successive terms of twenty-four (24) months.","Gia hạn quá dài":"Excessive renewal term","Mỗi bên cam kết giữ bí mật Thông tin Bảo mật của bên kia.":"Each party agrees to maintain the confidentiality of the other's Confidential Information.","Mọi sản phẩm bàn giao thuộc quyền sở hữu của Nhà cung cấp cho đến khi Khách hàng thanh toán mọi khoản nợ theo bất kỳ thỏa thuận nào.":"All deliverables remain Provider property until Client pays all sums outstanding under any agreement.","Vi phạm chéo":"Cross-default lien","Mỗi bên cam đoan có đầy đủ thẩm quyền ký kết Hợp đồng này.":"Each party warrants that it has full authority to enter into this Agreement.","Khách hàng sẽ bồi thường cho Nhà cung cấp trước mọi tổn thất, bất kể phát sinh dưới hình thức nào.":"Client shall indemnify Provider against all losses, howsoever arising.","Bồi thường 1 chiều":"Unilateral indemnity","Không bên nào chịu trách nhiệm đối với các thiệt hại gián tiếp hoặc hệ quả phát sinh.":"Neither party shall be liable for indirect or consequential damages.","Nhà cung cấp có thể chuyển nhượng Hợp đồng này mà không cần sự đồng ý.":"Provider may assign this Agreement without consent.","Đơn phương":"Unilateral assignment","Thông báo có thể được gửi qua email tới các địa chỉ ghi trong Đơn đặt hàng.":"Notices may be served by email to addresses set forth in the Order Form.","Hợp đồng này được điều chỉnh bởi luật pháp quy định trong Đơn đặt hàng.":"This Agreement shall be governed by the governing law specified in the Order Form.","Điều khoản {0} / {1}":"Clause {0} / {1}","Đóng menu":"Close menu","Hoàn tất. Liên kết dùng thử đang được gửi tới bạn (bản concept: không gửi email thật).":"All set. Your trial link is on its way (concept demo: no actual email sent).","Địa chỉ email có vẻ chưa đầy đủ.":"Please enter a valid email address."};
